const $=s=>document.querySelector(s),today=()=>new Date().toLocaleDateString('en-CA'),fmt=n=>Math.round(n).toLocaleString('ru-RU'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catalog=[{name:'Махи гирей',group:'Ноги · ягодицы · спина',tip:'Отведите таз назад, слегка согните колени. Разгибанием таза направьте гирю вперёд, сохраняя спину нейтральной. Руки направляют движение.',alt:'Становая тяга с гирей',reps:15},{name:'Гоблет-присед',group:'Ноги · корпус',tip:'Держите гирю у груди. Опуститесь в комфортный присед, направляя колени по линии стоп. Поднимитесь, опираясь на всю стопу.',alt:'Присед с собственным весом',reps:12},{name:'Жим гири стоя',group:'Плечи · трицепс',tip:'Держите гирю у плеча, запястье прямо. Напрягите корпус и выжмите гирю вверх без отклонения поясницы. Повторения в дневнике — суммарно на обе руки.',alt:'Жим гири сидя',reps:10},{name:'Тяга гири в наклоне',group:'Спина · бицепс',tip:'Наклонитесь с нейтральной спиной, свободной рукой обопритесь на устойчивую опору. Подтяните гирю к тазу и плавно опустите. Считайте повторения обеих рук суммарно.',alt:'Тяга двух гирь в наклоне',reps:12}];
const defaultProgram=()=>catalog.map(e=>({name:e.name,sets:3,weight:16,reps:e.reps,bells:1}));let db;try{db=JSON.parse(localStorage.getItem('girya-v1'))}catch{}db=db||{program:defaultProgram(),sessions:[],measurements:[],drafts:{}};let page='workout',selected=today(),period=8,graphExercise=db.program[0]?.name||catalog[0].name,timerId,seconds=90,trainingStart=Date.now();
function save(){localStorage.setItem('girya-v1',JSON.stringify(db))}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function draft(){if(!db.drafts[selected])db.drafts[selected]=db.program.map(e=>({name:e.name,sets:Array.from({length:e.sets},()=>({weight:e.weight,reps:e.reps,bells:e.bells||1,done:false}))}));return db.drafts[selected]}
function totals(ex){return ex.reduce((a,e)=>a+e.sets.reduce((n,s)=>n+(s.done?s.weight*s.reps*s.bells:0),0),0)}function completed(ex){return ex.reduce((a,e)=>a+e.sets.filter(s=>s.done).length,0)}
function title(k,h,p,extra=''){return `<div class="title-row"><div><div class="eyebrow">${k}</div><h1>${h}</h1><p style="margin:6px 0 0">${p}</p></div>${extra}</div>`}
function chart(name=graphExercise){let now=new Date(),points=Array.from({length:period},(_,i)=>{let end=new Date(now);end.setDate(end.getDate()-(period-1-i)*7);let start=new Date(end);start.setDate(start.getDate()-6);start.setHours(0,0,0,0);end.setHours(23,59,59,999);let v=db.sessions.filter(s=>new Date(s.date+'T12:00:00')>=start&&new Date(s.date+'T12:00:00')<=end).reduce((a,s)=>a+totals(s.exercises.filter(e=>e.name===name)),0);return {v,label:end.toLocaleDateString('ru-RU',{day:'numeric',month:'short'})}}),max=Math.max(1,...points.map(p=>p.v)),coords=points.map((p,i)=>`${35+i*320/(period-1)},${115-p.v/max*90}`);return `<svg class="chart" viewBox="0 0 380 150" role="img" aria-label="Тоннаж упражнения по неделям">${[25,70,115].map((y,i)=>`<line x1="35" y1="${y}" x2="355" y2="${y}" stroke="#edf0e7"/><text x="0" y="${y+3}">${fmt(max*(1-i/2))}</text>`).join('')}<path d="M${coords.join(' L')}" fill="none" stroke="#77964f" stroke-width="2.5"/>${coords.map(c=>{let [x,y]=c.split(',');return `<circle cx="${x}" cy="${y}" r="3.5" fill="#77964f"/>`}).join('')}${points.filter((_,i)=>i%2===0||i===period-1).map(p=>`<text x="${35+points.indexOf(p)*320/(period-1)}" y="142" text-anchor="middle">${p.label}</text>`).join('')}</svg>${db.sessions.length?'':'<div class="muted">График появится после первой сохранённой тренировки</div>'}`}
function workout(){let ex=draft(),done=completed(ex),all=ex.reduce((a,e)=>a+e.sets.length,0),week=new Date(selected+'T12:00:00');week.setDate(week.getDate()-((week.getDay()+6)%7));return title('Каждый подход имеет значение','Время стать сильнее','Твоя тренировка. Твой ритм. Твой прогресс.',`<span class="pill">◷ ${new Date(selected+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</span>`)+`<div class="stats"><div class="stat"><label>Тоннаж тренировки ↗</label><strong id="tonnage">${fmt(totals(ex))} <small>кг</small></strong><div class="sub">Вес × повторения × гири</div></div><div class="stat"><label>Выполнено подходов</label><strong id="sets-count">${done} <small>/ ${all}</small></strong><div class="sub">В своём темпе</div></div><div class="stat"><label>Тренировок за неделю</label><strong>${db.sessions.filter(s=>new Date(s.date+'T12:00:00')>=week&&new Date(s.date+'T12:00:00')<=new Date(week.getTime()+7*864e5)).length} <small>трен.</small></strong><div class="sub">Каждая — шаг вперёд</div></div><div class="stat"><label>Пульс сейчас ♡</label><strong id="heart-value">— <small>уд/мин</small></strong><div class="sub" id="heart-status">Датчик не подключён</div></div></div><div class="layout"><section><div class="card"><div class="between"><h2 style="margin:0">Твоя неделя</h2><input aria-label="Дата тренировки" type="date" id="training-date" value="${selected}" style="border:0;color:#819074;background:none;font-size:11px;max-width:125px"></div><div class="week">${Array.from({length:7},(_,i)=>{let d=new Date(week);d.setDate(d.getDate()+i);let iso=d.toLocaleDateString('en-CA');return `<button class="day ${iso===selected?'active':''}" data-date="${iso}">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'][i]}<strong>${d.getDate()}</strong><i>${db.sessions.some(s=>s.date===iso)?'●':'·'}</i></button>`}).join('')}</div><div class="between"><div><div class="eyebrow">Силовая тренировка</div><h2 style="margin:7px 0">Гири. Базовая программа</h2><span class="muted">${ex.length} упражнения · ${all} подходов</span></div><span class="tag">Всё тело</span></div>${ex.map((e,i)=>`<article class="exercise"><div class="ex-head"><div class="ex-icon" aria-hidden="true"><svg width="27" height="31" viewBox="0 0 32 36"><path d="M10 13V9a6 6 0 0 1 12 0v4" fill="none" stroke="currentColor" stroke-width="3"/><path d="M7 14Q16 9 25 14L29 27Q29 34 16 34Q3 34 3 27Z" fill="currentColor"/></svg></div><div><h3>${esc(e.name)}</h3><p>${esc(catalog.find(c=>c.name===e.name)?.group||'Моя программа')}</p></div><button class="text-btn" data-info="${i}">ⓘ Техника</button></div><div class="set-head"><span>ПОДХОД</span><span>ВЕС, КГ</span><span>ПОВТОРЫ</span><span>ГИРИ, ШТ.</span><span>✓</span></div>${e.sets.map((s,j)=>`<div class="set ${s.done?'done':''}"><span>${j+1}</span>${['weight','reps','bells'].map(k=>`<input aria-label="${k==='weight'?'Вес':k==='reps'?'Повторения':'Количество гирь'} ${esc(e.name)} подход ${j+1}" type="number" min="${k==='weight'?0.5:1}" max="${k==='weight'?200:k==='reps'?1000:2}" step="${k==='weight'?0.5:1}" value="${s[k]}" data-ex="${i}" data-set="${j}" data-key="${k}">`).join('')}<button class="check" aria-label="Отметить подход ${j+1}" aria-pressed="${s.done}" data-check="${i},${j}">${s.done?'✓':'·'}</button></div>`).join('')}<button class="text-btn" data-add="${i}" style="margin-top:12px">＋ Добавить подход</button></article>`).join('')}<button class="primary finish" id="finish">Завершить тренировку · ${done} из ${all} подходов</button></div></section><section class="right"><div class="card"><div class="between"><h3 class="side-title">Твой прогресс</h3><span class="tag">8 недель</span></div><p style="font-size:10px">${esc(graphExercise)} · тоннаж, кг</p><div class="chart-box">${chart()}</div><button class="text-btn" data-goto="progress" style="padding-top:15px">Вся статистика ↗</button></div><div class="card"><div class="between"><h3 class="side-title">Таймер отдыха</h3><span class="muted">◷</span></div><div class="timer" id="timer-display">${timerText()}</div><div class="timer-actions"><button class="secondary" id="timer-minus">− 15 с</button><button class="primary" id="timer-toggle">${timerId?'Пауза':'Старт'}</button><button class="secondary" id="timer-plus">+ 15 с</button></div></div><div class="card tip"><strong>✧ Сила в регулярности</strong><p>Отмечай каждый выполненный подход. Прогресс складывается из небольших усилий, которые ты повторяешь.</p><div class="progress-track"><div style="width:${all?done/all*100:0}%"></div></div><p style="margin-bottom:0">${done} из ${all} подходов сегодня</p></div><div class="card"><h3 class="side-title">◎ Время для замеров?</h3><p style="font-size:11px">${measurementDue()?'Обнови показатели тела в этом месяце.':'Замеры за этот месяц сохранены.'}</p><button class="text-btn" data-goto="body">Перейти к замерам →</button></div></section></div>`}
function measurementDue(){return !db.measurements.some(m=>m.date.slice(0,7)===today().slice(0,7))}
function progress(){return title('Видеть результат','Твой прогресс','Каждая тренировка становится частью твоей истории.')+`<div class="card"><div class="between"><select id="graph-ex" aria-label="Упражнение" style="max-width:260px">${[...new Set([...db.program.map(e=>e.name),...db.sessions.flatMap(s=>s.exercises.map(e=>e.name))])].map(n=>`<option ${n===graphExercise?'selected':''}>${esc(n)}</option>`).join('')}</select><select id="period" style="width:130px" aria-label="Период"><option value="4" ${period===4?'selected':''}>4 недели</option><option value="8" ${period===8?'selected':''}>8 недель</option></select></div><h2>Тоннаж по неделям <span class="muted">кг</span></h2>${chart()}</div><div class="card"><h2>История тренировок</h2>${db.sessions.length?db.sessions.slice().reverse().map(s=>`<div class="history-row"><span>${new Date(s.date+'T12:00:00').toLocaleDateString('ru-RU')}</span><span>${completed(s.exercises)} подходов</span><b>${fmt(totals(s.exercises))} кг</b></div>`).join(''):'<div class="empty">Заверши первую тренировку — здесь появится история.</div>'}</div>`}
function program(){return title('Твоя система','Моя программа','Редактируй упражнения или загрузи собственную программу.')+`<div class="card"><div class="between"><h2>Программа тренировок</h2><label class="secondary" style="cursor:pointer">↑ Загрузить CSV / JSON<input type="file" id="import" accept=".csv,.json" hidden></label></div><p style="font-size:11px">CSV: упражнение;подходы;вес;повторения;гири. Повторения для упражнений одной рукой указывай суммарно на обе руки.</p><form id="program-form"><div style="overflow-x:auto"><table><thead><tr><th>Упражнение</th><th>Подходы</th><th>Вес, кг</th><th>Повторы</th><th>Гири</th><th></th></tr></thead><tbody>${db.program.map((e,i)=>`<tr><td><input aria-label="Упражнение" required name="name-${i}" value="${esc(e.name)}" style="width:170px"></td>${['sets','weight','reps','bells'].map(k=>`<td><input aria-label="${k}" required name="${k}-${i}" type="number" min="${k==='weight'?0.5:1}" max="${k==='sets'?20:k==='weight'?200:k==='bells'?2:1000}" step="${k==='weight'?0.5:1}" value="${e[k]}" style="width:60px"></td>`).join('')}<td><button type="button" class="text-btn" data-remove="${i}" aria-label="Удалить упражнение">×</button></td></tr>`).join('')}</tbody></table></div><div class="between" style="margin-top:20px"><button type="button" id="program-add" class="secondary">＋ Упражнение</button><button class="primary">Сохранить программу</button></div></form><p class="muted">Изменения применятся к новым тренировкам. Начатые тренировки сохраняют свои подходы.</p></div>`}
function bodyPage(){let fields={weight:'Вес, кг',chest:'Грудь, см',waist:'Талия, см',hips:'Бёдра, см',arm:'Плечо, см',thigh:'Бедро, см'};return title('Больше, чем цифры','Антропометрия','Один замер в месяц — полная картина изменений.',`<span class="pill">${measurementDue()?'● Пора обновить замеры':'✓ Замеры актуальны'}</span>`)+`<div class="layout"><div><div class="card"><h2>Новый замер</h2><form id="body-form"><div class="form-grid"><label class="field">Дата<input name="date" type="date" required value="${today()}"></label>${Object.entries(fields).map(([k,v])=>`<label class="field">${v}<input name="${k}" type="number" step="0.1" min="1" max="500" ${k==='weight'?'required':''} placeholder="—"></label>`).join('')}</div><button class="primary" style="margin-top:22px">Сохранить замеры</button></form></div><div class="card"><h2>История замеров</h2><div style="overflow:auto">${db.measurements.length?`<table><tr><th>Дата</th>${Object.values(fields).map(v=>`<th>${v}</th>`).join('')}</tr>${db.measurements.slice().reverse().map(m=>`<tr><td>${esc(m.date)}</td>${Object.keys(fields).map(k=>`<td>${m[k]||'—'}</td>`).join('')}</tr>`).join('')}</table>`:'<div class="empty">Добавь первый замер, чтобы отслеживать изменения.</div>'}</div></div></div><div class="card" style="height:fit-content"><h3>Ежемесячное напоминание</h3><p style="font-size:12px">В начале каждого месяца приложение напомнит о замерах при открытии.</p><button class="secondary" id="calendar">↓ Добавить в календарь</button><p class="muted">Ежемесячное событие с уведомлением. Время можно изменить в своём календаре.</p></div></div>`}
function figure(){return `<div class="exercise-visual"><svg viewBox="0 0 160 120" aria-label="Условная иллюстрация атлета с гирей"><circle cx="78" cy="20" r="10" fill="#809870"/><path d="M78 33L71 65 47 99M71 65L100 99M76 38L101 58 124 56" fill="none" stroke="#456448" stroke-width="9" stroke-linecap="round"/><path d="M119 66a6 6 0 1 1 12 0" fill="none" stroke="#456448" stroke-width="3"/><rect x="114" y="66" width="23" height="20" rx="8" fill="#456448"/><path d="M28 107h115" stroke="#d2ddc4" stroke-width="2"/></svg></div>`}
function library(){return title('Двигайся уверенно','Библиотека упражнений','Техника, основные мышцы и варианты замены.')+`<div class="library">${catalog.map((e,i)=>`<div class="card">${figure()}<div class="eyebrow">${e.group}</div><h2>${e.name}</h2><p>${e.tip}</p><div class="tag" style="display:inline-block">Замена: ${e.alt}</div><button class="text-btn" data-library="${i}" style="display:block;margin-top:17px">Подробнее и видео ↗</button></div>`).join('')}</div>`}
function render(){const titles={workout:'Тренировка',program:'Моя программа',progress:'Прогресс',body:'Антропометрия',library:'Упражнения'};$('#breadcrumb').textContent=titles[page];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#app').innerHTML=({workout,program,progress,body:bodyPage,library}[page])();bind()}
function showInfo(e){$('#modal-content').innerHTML=figure()+`<h2>${esc(e.name)}</h2><p>${esc(e.tip||'Добавьте описание техники для своего упражнения в программе. Для этого упражнения пока нет инструкции в справочнике.')}</p>${e.alt?`<p><b>Замена:</b> ${esc(e.alt)}</p><a class="primary" style="display:inline-block;text-decoration:none" target="_blank" rel="noopener" href="https://www.youtube.com/results?search_query=${encodeURIComponent(e.name+' техника выполнения гиря')}">Найти видео техники ↗</a>`:''}`;$('#modal').showModal()}
function bind(){document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>navigate(b.dataset.goto));document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selected=b.dataset.date;render()});if($('#training-date'))$('#training-date').onchange=e=>{if(e.target.value){selected=e.target.value;render()}};document.querySelectorAll('[data-key]').forEach(input=>input.onchange=()=>{if(!input.checkValidity()){input.reportValidity();render();return}draft()[input.dataset.ex].sets[input.dataset.set][input.dataset.key]=+input.value;save();render()});document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{let [i,j]=b.dataset.check.split(',');let s=draft()[i].sets[j];s.done=!s.done;save();render()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{let e=draft()[b.dataset.add];e.sets.push({...e.sets.at(-1),done:false});save();render()});document.querySelectorAll('[data-info]').forEach(b=>b.onclick=()=>{let e=draft()[b.dataset.info];showInfo(catalog.find(c=>c.name===e.name)||e)});document.querySelectorAll('[data-library]').forEach(b=>b.onclick=()=>showInfo(catalog[b.dataset.library]));if($('#finish'))$('#finish').onclick=()=>{if(!completed(draft()))return toast('Сначала отметь выполненные подходы');let session={date:selected,exercises:structuredClone(draft()),minutes:Math.round((Date.now()-trainingStart)/60000)};let index=db.sessions.findIndex(s=>s.date===selected);if(index>=0)db.sessions[index]=session;else db.sessions.push(session);save();toast('Тренировка сохранена. Отличная работа!');navigate('progress')};if($('#timer-toggle')){$('#timer-toggle').onclick=toggleTimer;$('#timer-minus').onclick=()=>{seconds=Math.max(0,seconds-15);updateTimer()};$('#timer-plus').onclick=()=>{seconds+=15;updateTimer()}}if($('#period'))$('#period').onchange=e=>{period=+e.target.value;render()};if($('#graph-ex'))$('#graph-ex').onchange=e=>{graphExercise=e.target.value;render()};if($('#program-form')){$('#program-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);db.program=db.program.map((_,i)=>Object.fromEntries(['name','sets','weight','reps','bells'].map(k=>[k,k==='name'?f.get(k+'-'+i).trim():+f.get(k+'-'+i)])));save();toast('Программа сохранена')};$('#program-add').onclick=()=>{captureProgram();db.program.push({name:'Новое упражнение',sets:3,weight:16,reps:10,bells:1});render()};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(db.program.length===1)return toast('Оставь хотя бы одно упражнение');captureProgram();db.program.splice(+b.dataset.remove,1);render()});$('#import').onchange=importProgram}if($('#body-form')){$('#body-form').onsubmit=e=>{e.preventDefault();let m=Object.fromEntries(new FormData(e.target));let i=db.measurements.findIndex(x=>x.date===m.date);if(i>=0)db.measurements[i]=m;else db.measurements.push(m);db.measurements.sort((a,b)=>a.date.localeCompare(b.date));save();render();toast('Замеры сохранены')};$('#calendar').onclick=calendar}}
function captureProgram(){let f=new FormData($('#program-form'));db.program=db.program.map((_,i)=>Object.fromEntries(['name','sets','weight','reps','bells'].map(k=>[k,k==='name'?f.get(k+'-'+i):+f.get(k+'-'+i)])))}
async function importProgram(e){try{let file=e.target.files[0];if(!file)return;let text=await file.text(),p;if(file.name.endsWith('.json')){let parsed=JSON.parse(text);p=Array.isArray(parsed)?parsed:parsed.program}else{p=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/).map(l=>l.split(/[;,]/)).filter(r=>!isNaN(+r[1])).map(r=>({name:r[0],sets:+r[1],weight:+r[2],reps:+r[3],bells:+r[4]||1}))}if(!Array.isArray(p)||!p.length||p.length>30||p.some(x=>!x.name||!Number.isInteger(x.sets)||x.sets<1||x.sets>20||!(x.weight>0&&x.weight<=200)||!Number.isInteger(x.reps)||x.reps<1||x.reps>1000||![1,2].includes(x.bells||1)))throw Error();db.program=p.map(x=>({...x,name:String(x.name).slice(0,100),bells:x.bells||1}));save();render();toast('Программа загружена')}catch{toast('Проверь формат: название;подходы;вес;повторы;гири')}}
function navigate(p){page=p;render();window.scrollTo(0,0)}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.page));function timerText(){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}function updateTimer(){if($('#timer-display'))$('#timer-display').textContent=timerText()}function toggleTimer(){if(timerId){clearInterval(timerId);timerId=null}else{if(!seconds)seconds=90;timerId=setInterval(()=>{seconds--;updateTimer();if(seconds<=0){clearInterval(timerId);timerId=null;navigator.vibrate?.([200,100,200]);toast('Отдых завершён — следующий подход');if($('#timer-toggle'))$('#timer-toggle').textContent='Старт'}},1000)}if($('#timer-toggle'))$('#timer-toggle').textContent=timerId?'Пауза':'Старт'}
function download(text,name,type){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}$('#export').onclick=()=>download(JSON.stringify(db,null,2),'girya-backup.json','application/json');function calendar(){let d=new Date();d.setMonth(d.getMonth()+1,1);let date=`${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}01`;download(`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//GIRYA//RU\r\nBEGIN:VEVENT\r\nUID:girya-monthly-measurements\r\nDTSTAMP:${today().replaceAll('-','')}T000000Z\r\nDTSTART:${date}T090000\r\nDURATION:PT15M\r\nRRULE:FREQ=MONTHLY;BYMONTHDAY=1\r\nSUMMARY:ГИРЯ — ежемесячные замеры\r\nBEGIN:VALARM\r\nTRIGGER:-PT10M\r\nACTION:DISPLAY\r\nDESCRIPTION:Время записать антропометрию\r\nEND:VALARM\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`,'girya-reminder.ics','text/calendar')}
let heartRate=null;$('#pulse').onclick=async()=>{if(!navigator.bluetooth)return toast('Для Bluetooth открой приложение в Chrome или Edge на Android / компьютере');try{let device=await navigator.bluetooth.requestDevice({filters:[{services:['heart_rate']}]});let server=await device.gatt.connect(),service=await server.getPrimaryService('heart_rate'),characteristic=await service.getCharacteristic('heart_rate_measurement');await characteristic.startNotifications();characteristic.addEventListener('characteristicvaluechanged',e=>{let v=e.target.value;heartRate=v.getUint8(0)&1?v.getUint16(1,true):v.getUint8(1);$('#pulse').textContent=`♡ ${heartRate} уд/мин`;if($('#heart-value'))$('#heart-value').innerHTML=`${heartRate} <small>уд/мин</small>`;if($('#heart-status'))$('#heart-status').textContent='Датчик подключён'});device.addEventListener('gattserverdisconnected',()=>{$('#pulse').textContent='♡ Подключить пульс';if($('#heart-status'))$('#heart-status').textContent='Соединение потеряно';if($('#heart-value'))$('#heart-value').innerHTML='— <small>уд/мин</small>'});toast('Датчик подключён. Ожидаем измерение')}catch(e){toast(e.name==='NotFoundError'?'Подключение отменено':'Не удалось подключить датчик. Попробуй ещё раз')}};render();

